function UIPassportDialog:SpecialChannelLogin()
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    ---@type UserComponent
    local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
    HttpModule.RequestBodyMeta.SessionId = ""
    HttpModule.RequestBodyMeta.PlayerId = ""
    HttpModule.RequestBodyMeta.UserId = ""
    self.loginIng = true
    local userDojo = userComp.userInfo
    userDojo.lastLoginServerId = 0 ---重置掉数据
    local channelData = {
        openId = userDojo.openId, loginTimestamp = userDojo.timestamp, loginSign = userDojo.sdkSign
    }
    -- 判断身份证信息是否合法
    if isNotNull(userDojo.idNo) and string.len(tostring(userDojo.idNo)) > 5 then
        -- 合法传输t.idNo
        channelData.idNumber = userDojo.idNo
    end
    local isFinish = false
    ---登录的逻辑
    GameUtils.Request(Interfaces.ChannelLogin ..'/' .. os.time(), channelData,
            function(request, response)
                isFinish = true
                if checkNumber(response.errCode) == 0 then
                    local data = checkTable(response.data)
                    data.is_guest = userComp.userInfo.isGuest
                    data.ignore = true
                    userComp:Initial(data)

                    if checkInt(data.isQueueOpened) == 1 and tonumber(data.queueNum) ~= 0 then
                        userComp:GoToQueueDialog(data.queueNum, function()
                            Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN, data = data })
                        end)
                    else
                        Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN, data = data })
                    end
                    local servers = userComp.userInfo.servers
                    if checkInt(userComp.userInfo.lastLoginServerId) > 0 then
                        HttpModule.RequestBodyMeta.serverId = tostring(userComp.userInfo.lastLoginServerId)
                        ---@type UserComponent
                        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                        if isNotNull(userComponent) then
                            userComponent:SetRequestBodyMetaServerAreaId()
                        end
                    end
                    local serverDojo = userComp:GetServerById(userComp.userInfo.lastLoginServerId)
                    local sumPayCumulative = 0
                    if userComp.userInfo.servers and #userComp.userInfo.servers > 0 then
                        for k, v in pairs(userComp.userInfo.servers) do
                            sumPayCumulative = checkInt(v.payCumulative) +  sumPayCumulative
                        end
                        userComp:SetSumPayCumulative(sumPayCumulative)
                    end
                    --  设置玩家角色
                    if servers and #servers > 0 then
                        -- 此处如果没有roleId 不上传角色信息
                        if serverDojo then
                            if checkInt(serverDojo.playerId) > 0 and checkInt(serverDojo.playerLevel) > 0 then
                                local roles = {
                                    serverId = serverDojo.serverId,
                                    serverName = serverDojo.serverName,
                                    roleId = serverDojo.playerId,
                                    roleName = serverDojo.playerName,
                                    roleLevel = serverDojo.playerLevel,
                                    channelId = tostring(GameUtils.GetChannelId()),
                                    RechargePts = tostring(sumPayCumulative)
                                    -- gameJson = self:GetGameJsonStr()
                                }
                                -- 用于用户中心使用 ， 玩家id ， 玩家昵称  ， 服务器id ， 服务器名称
                                SDKService:GetInstance():SetGameRole(roles)
                            end
                        end
                    end
                end
            end, function(exception)
                isFinish = true
                GameUtils.Toast(exception.Message)
            end)
    while not isFinish do
        coroutine.yield()
    end
end

function UIPassportDialog:UpdateButtonEntrance()
    if isNotNull(self.ButtonEntrance) then
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        if isNotNull(userComponent) then
            local serverId = 0
            local cuurentServerId = checkInt(userComponent.userInfo.cuurentServerId)
            if cuurentServerId > 0 then
                serverId = checkNumber(cuurentServerId)
            end
            ---@type ServerDojo
            local serverDojo
            --print("===>>", serverId)
            if serverId <= 0 then
                serverId = checkNumber(PlayerPrefsUtility.GetEncryptedString("LOCAL_SERVER_ID", "0"))
            end
            --print("===>>", serverId)
            if serverId <= 0 then
                serverId = checkInt(userComponent.userInfo.lastLoginServerId)
            end
            --print("===>>", serverId)
            if checkInt(serverId) <= 0 then
                serverDojo = userComponent:GetNewServerByServerList()
                if serverDojo and checkNumber(serverDojo.serverId) == 999 then
                    PlayerPrefsUtility.SetEncryptedString("LOCAL_SERVER_ID", tostring(serverDojo.serverId))
                    PlayerPrefsUtility.Save()
                end
            else
                serverDojo = userComponent:GetServerListById(serverId)
                if isNull(serverDojo) then
                    serverDojo = userComponent:GetNewServerByServerList()
                    if serverDojo and checkNumber(serverDojo.serverId) == 999 then
                        PlayerPrefsUtility.SetEncryptedString("LOCAL_SERVER_ID", tostring(serverDojo.serverId))
                        PlayerPrefsUtility.Save()
                    end
                end
            end
            if isNotNull(serverDojo) then
                if checkNumber(serverDojo.serverId) == 999 and not string.isEmpty(serverDojo.host) then
                    ---物理分服国服
                    HttpModule.ServerHost = checkString(serverDojo.host)
                    HttpModule.Instance.Ip = checkString(serverDojo.host)
                    CfUtils.StartCoroutineWithBlocker(function()
                        xTry(function()
                            cs_coroutine.yield_return(self:SpecialChannelLogin())
                        end)
                    end)
                else
                    local cnServer = userComponent:GetServerListById(999)
                    if not isNull(cnServer) and HttpModule.ServerHost ~= self.configServerHost and not string.isEmpty(self.configServerHost) then
                        HttpModule.ServerHost = self.configServerHost
                        HttpModule.Instance.Ip = checkString(self.configServerHost)
                        CfUtils.StartCoroutineWithBlocker(function()
                            xTry(function()
                                cs_coroutine.yield_return(self:SpecialChannelLogin())
                            end)
                        end)
                    end
                end
                local TxtName = self.ButtonEntrance.transform:Find("TxtName")
                CfUtils.FillText(TxtName, serverDojo.serverName)
                local ImgStatusIcon = self.ButtonEntrance.transform:Find("ImgStatusIcon")
                if checkInt(serverDojo.status) == 0 then
                    KTool.SetActive(ImgStatusIcon, false)
                else
                    CfUtils.SetUISwitchImage(ImgStatusIcon, serverDojo.status)
                end
                userComponent:Initial({ serverId = serverDojo.serverId, cuurentServerId = serverDojo.serverId })
            else
                local ImgStatusIcon = self.ButtonEntrance.transform:Find("ImgStatusIcon")
                KTool.SetActive(ImgStatusIcon, false)
                local TxtName = self.ButtonEntrance.transform:Find("TxtName")
                CfUtils.FillText(TxtName, localize("请选服"))
            end

        end
    end
end

