function UIPassportDialog:StartGameEvent(isUpdate)
    ---直接开始进行检测更新或者小包下载
    if isNull(isUpdate) then
        self:EnterUserUpdate()
    end
    local isSmallPackage = IsSmallPackage()
    local IsNewPreDownloadOpen = self:IsNewPreDownloadOpen()
    if not isSmallPackage and IsNewPreDownloadOpen then
        CfUtils.SetActive(self.StartGamePanel, false)
        CfUtils.SetActive(self.PreDownloadPanel, true)
        if SDKService:GetInstance():IsJP() then
            CfUtils.SetActive(self.PreDownloadPanel.transform:Find("root/BtnGroup/BtnAssociation"), false)
        end
        SetButtonAction(self.PreDownloadPanel.transform:Find("root/BtnGroup/BtnAssociation"), function()
            ----打开社区
            if SDKService:GetInstance():IsZm() then
                CfUtils.OpenURL('https://x.com/catfantasyen')    
            else     
                CfUtils.OpenURL('https://game.naver.com/lounge/Cat_Fantasy/home')    
            end
        end)
        SetButtonAction(self.PreDownloadPanel.transform:Find("root/BtnGroup/BtnNotice"), function()
            ----打开
            UIModule.OpenDialog({ id = Constants.UITypeIds.UINoticeDialog })
        end)
    else
        CfUtils.SetActive(self.PreDownloadPanel, false)
        KTool.SetActive(self._startButton.gameObject, true)
        KTool.SetActive(self.LoginPanel.gameObject, false)
        KTool.SetActive(self.StartGamePanel.gameObject, true)
        if not CfUtils.IsActive(self.ButtonEntrance) then
            --window的时候可以登出
            if GameUtils.IsWindow() then
                CfUtils.SetActive(self.StartGamePanel.transform:Find("root/BtnGroup/BtnExit"), true)
            end
            -- 用户中心 只有登录成功才显示
            ---@type SDKService
            local sdkService = SDKService:GetInstance()
            local trans = self.StartGamePanel:Find("root/BtnGroup/UserCenter")
            if isNotNull(trans) then
                KTool.SetActive(trans.gameObject, (sdkService:IsForeignSDK() or (sdkService.IsOneStore and sdkService:IsOneStore())) and (checkInt(IS_REVIEW_INT) <= 0))
