function UIPassportDialog:SwitchLogin()
    ---@type SDKService
    local sdkService = SDKService:GetInstance()
    CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
    ---去登录页面
    if sdkService:IsCommonSDK() then
        ---@type UserComponent
        local userComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.UserComponent)
        if userComp and checkNumber(userComp.userInfo.lastLoginServerId) == 999 then
            PlayerPrefsUtility.SetEncryptedString("LOCAL_SERVER_ID", "")
            PlayerPrefsUtility.Save()
            ---老兵服的情况下如果切账号，直接先还原到正式服去
            if HttpModule.ServerHost ~= self.configServerHost and not string.isEmpty(self.configServerHost) then
                HttpModule.ServerHost = self.configServerHost
                HttpModule.Instance.Ip = checkString(self.configServerHost)
            end
        end
        if KTool.IsMobile() then
            sdkService:SwitchLogin()
        else
            sdkService:Login(true)
        end
    else
        KTool.SetActive(self._startButton.gameObject, true)
        KTool.SetActive(self.LoginPanel.gameObject, true)
        local rootTrans = self.LoginPanel.transform:Find("Root")
        if not isNull(rootTrans) then
            KTool.SetActive(rootTrans.gameObject, true)
        end
        KTool.SetActive(self.RegistPanel.gameObject, false)
        KTool.SetActive(self.StartGamePanel.gameObject, false)
    end
end
