function UIPassportDialog:OnNoticeClosed()
    if self._eventHandler then
        Events.RemoveListener("OPEN_NOTICE_VIEW_CLOSE", self._eventHandler)
    end
    self._eventHandler = nil
    self:AutoSDKLogin()
end

function UIPassportDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast("UPDATE_REPAIR_HIDE_ACTION")
        GameUtils.CloseWaterMark()
        if Config.DEBUG_QUICK_START then
            self:AutoSDKLogin()
            return
        end
        execute_task_everyday_hour('OPEN_NOTICE_VIEW_CLOSE', 5, function()
            Events.RemoveListener("OPEN_NOTICE_VIEW_CLOSE", self._eventHandler)
            self._eventHandler = nil
            self._eventHandler = Bind(self, self.OnNoticeClosed)
            Events.AddListener("OPEN_NOTICE_VIEW_CLOSE", self._eventHandler)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UINoticeDialog })
        end, function()
            ---已经弹出过
            self:AutoSDKLogin()
        end)
        self.controller:StartCoroutine(util.cs_generator(function()
            xTry(function()
                while true do
                    coroutine.yield()
                    if self.isBlocked then
                        coroutine.yield(WaitForSecondsRealtime(3))
                        self.isBlocked = false
                        blockerInstance:RemoveCondition("START_GAME_BUTTON")
                    end
                end
            end)
        end))
    end))
    return coWait
end

function UIPassportDialog:AutoSDKLogin()
    local sdkService = SDKService:GetInstance()
    local parameters = self.controller.Argument.parameters
    if isNotNull(parameters) and parameters.backGame then
        if sdkService:IsDmm() then
            sdkService:Login()
        else
            self:SwitchLogin()    
        end
    else
        local isSmall = IsSmallPackage()
        if isSmall and not IS_REVIEW then
            GameUtils.Request("User/update", {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local userUpdateInfo = checkTable(response.data)
                    if checkNumber(userUpdateInfo.isReview) > 0 then
                        local dialog = UIModule.CurrentScreen:GetDialog(13)
                        if dialog and dialog.Env then
                            ---@type GameStartInit
                            local env = dialog.Env
                            env.userUpdateInfo = clone(userUpdateInfo)
                        end
                        ---审核服务器,更改服务器
                        CS.Engine.Http.HttpModule.ServerHost = checkString(userUpdateInfo.reviewUrl)
                        IS_REVIEW = true
                        IS_REVIEW_INT = checkNumber(userUpdateInfo.isReview)
                    end
                    sdkService:Login()
                end
            end)
        else
            sdkService:Login()
        end
    end
end

