function UIPassportDialog:RealStartGame()
    --local isSmall = IsSmallPackage()
    ----已经下载完小包的情况下, 但是热更新未执行完成
    --if not isSmall and checkNumber(KCookie.Get("IS_UPDATE_SUCCESS")) == 0 and self.isNewSmallPackage == true then
    --    return
    --end
    ----开始正常的进入游戏的流程
    KCookie.RemoveAllListener("IS_UPDATE_SUCCESS")
    --self:AutoSDKLogin()
    if SDKService:GetInstance().isLogin then
        self.isBlocked = true
        ---@type ECSWorldMgr
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        ---@type ECSEntity
        local entity = world:GetEntity(Constants.PlayerEntityId)
         ---@type UserComponent
        local userComp = entity:GetComp(ECSComponentType.Constants.UserComponent)
        local lastServerId = checkNumber(userComp.userInfo.lastLoginServerId)
        local cuurentServerId = checkInt(userComp.userInfo.cuurentServerId)
        if cuurentServerId == 0 then
            cuurentServerId = lastServerId
        end
        local isSupport = ThirdDownloadManager:IsSupportThirdPackage()
        local serverInfo = userComp:GetServerById(cuurentServerId)
        local isOpen = ThirdDownloadManager:IsMainOpenDownloadThirdPackage(serverInfo  and serverInfo.chapterId)
        if isSupport and isOpen and (not IsSmallPackage())  then
            KTool.SetActive(self.StartGamePanel , false) 
            Events.Broadcast("PlayerDownloadThirdEvent" ,{func = function()
                ---if is login, then enter game
                    if Config.DEBUG_QUICK_START then
                        self:_StartGoGame()
                    else
                        self:StartEnterGame()
                    end
            end ,
            cancelFunc = function()
                KTool.SetActive(self.StartGamePanel , true) 
            end  })
        else 
            blockerInstance:AddCondition("START_GAME_BUTTON")
            ---if is login, then enter game
            if Config.DEBUG_QUICK_START then
                self:_StartGoGame()
            else
               self:StartEnterGame()
            end
        end
       
        --SDKService:GetInstance():SwitchLogin(function()
        --    self:SwitchLogin()
        --end)
    else
        self:AutoSDKLogin()
    end
    xRecord.record('15-001')
end

function UIPassportDialog:StartEnterGame()
    if SDKService:GetInstance():IsDuoLe() then
        if self:IsDuoLePrivacyAgree() then
            SDKService:GetInstance():StartEnterGame()    
        else
            GameUtils.SecondConfirm(localize("请先阅读并同意平台用户协议条款、隐私政策"), function()
                KTool.SetActive(self.ImgSelect , true) 
                self:WriteDuoLePrivacyAgree("1")
            end, function()
                
            end)
        end
    else
        SDKService:GetInstance():StartEnterGame()        
    end
end

function UIPassportDialog:IsDuoLePrivacyAgree()
    local isAgree = PlayerPrefsUtility.GetEncryptedString("DuoLePrivacyAgree" ,"0")
    return checkInt(isAgree) == 1
end

function UIPassportDialog:WriteDuoLePrivacyAgree(isAgree)
    PlayerPrefsUtility.SetEncryptedString("DuoLePrivacyAgree" ,isAgree)
    PlayerPrefsUtility.Save()
end

