                                    --    GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, Constants.LoadingType.MainHome, true)
                                    --
                                    --end


                                else
                                    GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, Constants.LoadingType.MainHome, true)

                                end
                                local SDKService = import('Game.Entry.SDKService')
                                local sdkService = SDKService:GetInstance()
                                sdkService:UploadRole(data.playerId, data.playerName)
                                sdkService:TrackReYunEvent("login", { accountID = tostring(data.playerId) })
                            else
                                CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
                                KTool.SetActive(self._startButton.gameObject, true)
                                self.isEntered = false
                            end
                        end)
                    end
                end
            end
        else
            CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
            ---不存在上次的账户记录显示登录显示
            local channelId = GameUtils.GetChannelId()
            if channelId < 50 then
                KTool.SetActive(self.LoginPanel.gameObject, true)
                KTool.SetActive(self.RegistPanel.gameObject, false)
                KTool.SetActive(self.StartGamePanel.gameObject, false)
            else
                KTool.SetActive(self.LoginPanel.gameObject, false)
                KTool.SetActive(self.RegistPanel.gameObject, false)
            end
        end
    else
        ---显示登录界面
        local channelId = GameUtils.GetChannelId()
        if channelId < 50 then
            ---非sdk的情况下
            KTool.SetActive(self.LoginPanel.gameObject, true)
            KTool.SetActive(self.RegistPanel.gameObject, false)
            KTool.SetActive(self.StartGamePanel.gameObject, false)
        else
            KTool.SetActive(self.LoginPanel.gameObject, false)
            KTool.SetActive(self.RegistPanel.gameObject, false)
        end
    end
end

--检查4个op关是否全部通过
function UIPassportDialog:CheckOpStatus()
    local IsOpenOp = AppEngine.GetConfig("Engine.Dev", "IsOpenOp")
    if checkNumber(IsOpenOp) > 0 then
        local curOP = QuestConfMgr:GetInstance():GetCurOpId()
        return curOP ~= 0
    else
        return false
    end
    --return true
end

--有未通过的就继续过op
function UIPassportDialog:EnterOpStatus()
    UIModule.CloseDialogById(Constants.UITypeIds.PassportDialog)
    UIModule.CloseDialogById(GameInitScene, true)
    MainQuestMapMgr:GetInstance():EnterQuestOp(QuestConfMgr:GetInstance():GetCurOpId())
    -- MainQuestMapMgr:GetInstance():EnterQuestOp(100020)
end

--- 直接进入op第四关
function UIPassportDialog:DirectEnterOp4()
    UIModule.CloseDialogById(Constants.UITypeIds.PassportDialog)
    UIModule.CloseDialogById(GameInitScene, true)
    MainQuestMapMgr:GetInstance():EnterQuestOp(Constants.QUEST_OP_LEVEL[4])
end

---预下载功能创建角色
function UIPassportDialog:PreDownloadCreate()
    GameUtils.Request(Interfaces.PlayerCreate, {}, function(request, response)

        if checkNumber(response.errCode) == 0 then
            --checkin logical
            local data = checkTable(response.data)
            local playerId = data.playerId
            local playerName = data.playerName
            ---@type ECSWorldMgr
            local worldMgr = ECSWorldMgr:GetInstance()
            ---@type ECSWorld
            local world = worldMgr:GetWorld(Constants.GameWorld)
            ---@type ECSEntity
            local entity = world:GetEntity(Constants.PlayerEntityId)
            local playerComponent = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
            if not isNull(playerComponent) then
                playerComponent.playerDojo:PlayerId(playerId)
                playerComponent.playerDojo.playerName = playerName
                playerComponent.playerDojo.serverTime = checkNumber(data.serverTime)
                local sdkService = SDKService:GetInstance()
                sdkService:CreateRole(playerId, playerName)
                --- checkin
                GameUtils.Request(Interfaces.PlayerCheckIn, nil, Bind(self, self.PreDownloadCheckInOnSuccess))
            end
        else
            CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
            KTool.SetActive(self._startButton.gameObject, true)
            self.isEntered = false
        end
    end)
end

function UIPassportDialog:PreDownloadCheckInOnSuccess(request, response)
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)

    if checkNumber(response.errCode) == 0 then
        local data = checkTable(response.data)
        --if entity:IsCompExistsByName(ECSComponentType.Constants.PlayerComponent) then
        --    entity:RemoveComp(ECSComponentType.Constants.PlayerComponent)
        --end
        ---@type PlayerComponent
        local playerComp = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
        playerComp:LoadPlayer(data)
        UIModule.CloseDialogById(Constants.UITypeIds.SelectServerDialog, true)
        if self:CheckOpStatus() then
            self:EnterOpStatus()
        else
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, parameters = { isPreDownload = true } }, {}, Constants.LoadingType.MainHome, true)
        end
        local sdkService = SDKService:GetInstance()
        sdkService:CreateRole(data.playerId, data.playerName)
    else

        CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
        KTool.SetActive(self._startButton.gameObject, true)
        self.isEntered = false
    end
end

function UIPassportDialog:EnterUserUpdate()
    local isSmall = IsSmallPackage()
    if isSmall then
        Events.Broadcast("PreDownloadCheckInOnSuccess")
    end
end

