---IsNewPreDownloadOpen
---是否是新的预下载开启了
function UIPassportDialog:IsNewPreDownloadOpen()
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if userComponent then
        return checkNumber(userComponent.userInfo.isPrePlayOpened) > 0
    end
    return false
end

---是否为预下载状态
---@return boolean
function UIPassportDialog:IsPreDownload()
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    local isSmallPackage = checkNumber(AppEngine.GetConfig("Engine", "IsSmallPackage", false))
    local preVersion = PlayerPrefsUtility.GetEncryptedString("SmallPackageDownloaded", "")
    local isSmall = false
    if isSmallPackage == 1 and preVersion ~= CS.UnityEngine.Application.version then
        ---最新的分包的逻辑，要进行检测更新相关的逻辑
        isSmall = true
    end
    return isSmall
end

function UIPassportDialog:OnCheckinSuccess(request, response)
    if checkNumber(response.errCode) == 0 then
        local data = checkTable(response.data)
        ---@type ECSWorldMgr
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        ---@type ECSEntity
        local entity = world:GetEntity(Constants.PlayerEntityId)
        --if entity:IsCompExistsByName(ECSComponentType.Constants.PlayerComponent) then
        --    entity:RemoveComp(ECSComponentType.Constants.PlayerComponent)
        --end
        ---@type PlayerComponent
        local playerComponent = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
        playerComponent:LoadPlayer(data)
        UIModule.CloseDialogById(Constants.UITypeIds.SelectServerDialog, true)
        if self:CheckOpStatus() then
            self:EnterOpStatus()
        else
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, Constants.LoadingType.MainHome, true)
        end
    else
        self.isEntered = false
        CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
        KTool.SetActive(self._startButton.gameObject, true)
    end
end

