function UIPassportDialog:OnFocus(focus)
    if focus and (not self.isFocused) then
        self.isFocused = true
        self:UpdateButtonEntrance()
    end
end

function UIPassportDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.sdkEvent)
        Events.RemoveListener("SDKLOGOUT", self.logOutEvent)
        blockerInstance:RemoveCondition("START_GAME_BUTTON")
        self.logOutEvent = nil
        self.sdkEvent = nil
        if self._eventHandler then
            Events.RemoveListener("OPEN_NOTICE_VIEW_CLOSE", self._eventHandler)
        end
        self._eventHandler = nil
        if not isNull(self.eventCB) then
            Events.RemoveListener(Constants.EventNames.UIGameInitEvent, self.eventCB)
            Events.RemoveListener(Constants.EventNames.ChangeAuthenticationValue, self.__eventChangeAuthenticationState)
        end
        if self.isReload then
            xTry(function()
                ---清除所有的倒计时
                CS.Engine.Lib.KCookie.PurgeCache()
                ---清缓存
                CS.Engine.Modules.LuaModule.Instance:ClearAllCache()
                ---清理配表
                CS.Engine.Modules.SettingModule.ClearCache()
                Unload()
                Events.Broadcast("UPDATE_REPAIR_UPDATE_ACTION")
            end)
        else
            if GameUtils.IsWindow() then
                Events.RemoveListener("WinEnterGame", self.EventWinSDK)
            end
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIPassportDialog